  1 | import { useCallback, useMemo, useRef, useState } from "react";
  2 | import type { Track } from "../types";
  3 | 
  4 | type SortField = "title" | "artist" | "duration";
  5 | type SortDirection = "asc" | "desc";
  6 | 
  7 | interface PlaylistProps {
  8 |   tracks: Track[];
  9 |   currentTrackId: string | null;
 10 |   isPlaying: boolean;
 11 |   onSelectTrack: (track: Track) => void;
 12 |   onReorderPlaylist?: (tracks: Track[]) => void;
 13 |   onDropFiles?: (files: FileList) => void;
 14 |   onToggleFavorite?: (trackId: string) => void;
 15 | }
 16 | 
 17 | function formatDuration(seconds: number): string {
 18 |   const mins = Math.floor(seconds / 60);
 19 |   const secs = Math.floor(seconds % 60);
 20 |   return `${mins}:${secs.toString().padStart(2, "0")}`;
 21 | }
 22 | 
 23 | function normalizeText(text: string): string {
 24 |   return text
 25 |     .normalize("NFD")
 26 |     .replace(/[\u0300-\u036f]/g, "")
 27 |     .toLowerCase();
 28 | }
 29 | 
 30 | function getSortValue(track: Track, field: SortField): string {
 31 |   switch (field) {
 32 |     case "title":
 33 |       return normalizeText(track.title);
 34 |     case "artist":
 35 |       return normalizeText(track.artist ?? "");
 36 |     case "duration":
 37 |       return String(track.duration).padStart(10, "0");
 38 |   }
 39 | }
 40 | 
 41 | export function Playlist({
 42 |   tracks,
 43 |   currentTrackId,
 44 |   isPlaying,
 45 |   onSelectTrack,
 46 |   onReorderPlaylist,
 47 |   onDropFiles,
 48 |   onToggleFavorite,
 49 | }: PlaylistProps) {
 50 |   const [dragOverIndex, setDragOverIndex] = useState<number | null>(null);
 51 |   const dragItemIndex = useRef<number | null>(null);
 52 |   const [isDragOver, setIsDragOver] = useState(false);
 53 |   const [searchQuery, setSearchQuery] = useState("");
 54 |   const [sortField, setSortField] = useState<SortField | null>(null);
 55 |   const [sortDirection, setSortDirection] = useState<SortDirection>("asc");
 56 | 
 57 |   // Filtro de busca
 58 |   const normalizedQuery = normalizeText(searchQuery);
 59 | 
 60 |   const handleSort = useCallback(
 61 |     (field: SortField) => {
 62 |       if (sortField === field) {
 63 |         // Toggle direction
 64 |         const newDirection = sortDirection === "asc" ? "desc" : "asc";
 65 |         setSortDirection(newDirection);
 66 |         // Reorder the playlist
 67 |         const sorted = [...tracks].sort((a, b) => {
 68 |           const aVal = getSortValue(a, field);
 69 |           const bVal = getSortValue(b, field);
 70 |           const cmp = aVal.localeCompare(bVal);
 71 |           return newDirection === "asc" ? cmp : -cmp;
 72 |         });
 73 |         onReorderPlaylist?.(sorted);
 74 |       } else {
 75 |         setSortField(field);
 76 |         setSortDirection("asc");
 77 |         const sorted = [...tracks].sort((a, b) => {
 78 |           const aVal = getSortValue(a, field);
 79 |           const bVal = getSortValue(b, field);
 80 |           return aVal.localeCompare(bVal);
 81 |         });
 82 |         onReorderPlaylist?.(sorted);
 83 |       }
 84 |     },
 85 |     [tracks, sortField, sortDirection, onReorderPlaylist]
 86 |   );
 87 | 
 88 |   const filteredTracks = useMemo(() => {
 89 |     if (!normalizedQuery) return tracks;
 90 |     return tracks.filter((track) => {
 91 |       const title = normalizeText(track.title);
 92 |       const artist = track.artist ? normalizeText(track.artist) : "";
 93 |       return title.includes(normalizedQuery) || artist.includes(normalizedQuery);
 94 |     });
 95 |   }, [tracks, normalizedQuery]);
 96 | 
 97 |   // Mapeia índice filtrado → índice original para drag & drop
 98 |   const filteredToOriginalIndex = useMemo(() => {
 99 |     if (!normalizedQuery) return null;
100 |     return filteredTracks.map((ft) => tracks.indexOf(ft));
101 |   }, [filteredTracks, tracks, normalizedQuery]);
102 | 
103 |   // Drag & drop de arquivos do sistema
104 |   const handleDragOverWindow = useCallback((e: React.DragEvent) => {
105 |     if (e.dataTransfer.types.includes("Files")) {
106 |       e.preventDefault();
107 |       e.stopPropagation();
108 |       setIsDragOver(true);
109 |     }
110 |   }, []);
111 | 
112 |   const handleDragLeaveWindow = useCallback((e: React.DragEvent) => {
113 |     e.preventDefault();
114 |     setIsDragOver(false);
115 |   }, []);
116 | 
117 |   const handleDropWindow = useCallback(
118 |     (e: React.DragEvent) => {
119 |       e.preventDefault();
120 |       e.stopPropagation();
121 |       setIsDragOver(false);
122 | 
123 |       if (e.dataTransfer.files && e.dataTransfer.files.length > 0) {
124 |         onDropFiles?.(e.dataTransfer.files);
125 |       }
126 |     },
127 |     [onDropFiles]
128 |   );
129 | 
130 |   const resolveOriginalIndex = useCallback(
131 |     (filteredIndex: number): number => {
132 |       if (filteredToOriginalIndex) {
133 |         return filteredToOriginalIndex[filteredIndex];
134 |       }
135 |       return filteredIndex;
136 |     },
137 |     [filteredToOriginalIndex]
138 |   );
139 | 
140 |   const handleDragStart = useCallback(
141 |     (e: React.DragEvent<HTMLLIElement>, filteredIndex: number) => {
142 |       const originalIndex = resolveOriginalIndex(filteredIndex);
143 |       dragItemIndex.current = originalIndex;
144 |       e.dataTransfer.effectAllowed = "move";
145 |       e.dataTransfer.setData("text/plain", String(originalIndex));
146 |       // Add a slight delay so the drag image shows properly
147 |       e.currentTarget.classList.add("dragging");
148 |     },
149 |     [resolveOriginalIndex]
150 |   );
151 | 
152 |   const handleDragEnd = useCallback(
153 |     (e: React.DragEvent<HTMLLIElement>) => {
154 |       e.currentTarget.classList.remove("dragging");
155 |       dragItemIndex.current = null;
156 |       setDragOverIndex(null);
157 |     },
158 |     []
159 |   );
160 | 
161 |   const handleDragOver = useCallback(
162 |     (e: React.DragEvent<HTMLLIElement>, filteredIndex: number) => {
163 |       e.preventDefault();
164 |       e.dataTransfer.dropEffect = "move";
165 |       setDragOverIndex(filteredIndex);
166 |     },
167 |     []
168 |   );
169 | 
170 |   const handleDragLeave = useCallback(() => {
171 |     setDragOverIndex(null);
172 |   }, []);
173 | 
174 |   const handleDrop = useCallback(
175 |     (e: React.DragEvent<HTMLLIElement>, dropFilteredIndex: number) => {
176 |       e.preventDefault();
177 |       const fromIndex = dragItemIndex.current;
178 |       const dropIndex = resolveOriginalIndex(dropFilteredIndex);
179 |       if (fromIndex === null || fromIndex === dropIndex) {
180 |         setDragOverIndex(null);
181 |         return;
182 |       }
183 | 
184 |       const reordered = [...tracks];
185 |       const [movedItem] = reordered.splice(fromIndex, 1);
186 |       reordered.splice(dropIndex, 0, movedItem);
187 | 
188 |       onReorderPlaylist?.(reordered);
189 |       dragItemIndex.current = null;
190 |       setDragOverIndex(null);
191 |     },
192 |     [tracks, onReorderPlaylist, resolveOriginalIndex]
193 |   );
194 | 
195 |   return (
196 |     <section
197 |       className={`playlist-panel ${isDragOver ? "playlist-drag-over" : ""}`}
198 |       onDragOver={handleDragOverWindow}
199 |       onDragLeave={handleDragLeaveWindow}
200 |       onDrop={handleDropWindow}
201 |     >
202 |       <div className="panel-header">PLAYLIST</div>
203 |       {isDragOver && (
204 |         <div className="playlist-drop-indicator">
205 |           📁 Solte os arquivos para adicionar à playlist
206 |         </div>
207 |       )}
208 |       <div className="playlist-search-container">
209 |         <input
210 |           type="text"
211 |           className="playlist-search-input"
212 |           placeholder="Buscar música..."
213 |           value={searchQuery}
214 |           onChange={(e) => setSearchQuery(e.target.value)}
215 |           aria-label="Buscar música na playlist"
216 |         />
217 |         {searchQuery && (
218 |           <button
219 |             className="playlist-search-clear"
220 |             onClick={() => setSearchQuery("")}
221 |             title="Limpar busca"
222 |             aria-label="Limpar busca"
223 |           >
224 |             ✕
225 |           </button>
226 |         )}
227 |       </div>
228 |       {searchQuery && (
229 |         <div className="playlist-search-count">
230 |           {filteredTracks.length === 0
231 |             ? "Nenhuma música encontrada"
232 |             : `${filteredTracks.length} de ${tracks.length} música${tracks.length !== 1 ? "s" : ""}`}
233 |         </div>
234 |       )}
235 |       <div className="playlist-sort-bar">
236 |         <button
237 |           className={`playlist-sort-btn ${sortField === "title" ? "active" : ""}`}
238 |           onClick={() => handleSort("title")}
239 |           title={`Ordenar por nome${sortField === "title" ? (sortDirection === "asc" ? " (A-Z)" : " (Z-A)") : ""}`}
240 |         >
241 |           Nome {sortField === "title" ? (sortDirection === "asc" ? "▲" : "▼") : ""}
242 |         </button>
243 |         <button
244 |           className={`playlist-sort-btn ${sortField === "artist" ? "active" : ""}`}
245 |           onClick={() => handleSort("artist")}
246 |           title={`Ordenar por artista${sortField === "artist" ? (sortDirection === "asc" ? " (A-Z)" : " (Z-A)") : ""}`}
247 |         >
248 |           Artista {sortField === "artist" ? (sortDirection === "asc" ? "▲" : "▼") : ""}
249 |         </button>
250 |         <button
251 |           className={`playlist-sort-btn ${sortField === "duration" ? "active" : ""}`}
252 |           onClick={() => handleSort("duration")}
253 |           title={`Ordenar por duração${sortField === "duration" ? (sortDirection === "asc" ? " (menor)" : " (maior)") : ""}`}
254 |         >
255 |           Duração {sortField === "duration" ? (sortDirection === "asc" ? "▲" : "▼") : ""}
256 |         </button>
257 |       </div>
258 |       <ul className="playlist">
259 |         {tracks.length === 0 ? (
260 |           <li className="playlist-item playlist-empty">
261 |             Nenhuma música na playlist
262 |           </li>
263 |         ) : filteredTracks.length === 0 ? (
264 |           <li className="playlist-item playlist-empty">
265 |             Nenhuma música encontrada
266 |           </li>
267 |         ) : (
268 |           filteredTracks.map((track, filteredIndex) => (
269 |             <li
270 |               key={track.id}
271 |               className={`playlist-item ${
272 |                 track.id === currentTrackId ? "active" : ""
273 |               } ${dragOverIndex === filteredIndex ? "drag-over" : ""}`}
274 |               draggable
275 |               onClick={() => onSelectTrack(track)}
276 |               onDragStart={(e) => handleDragStart(e, filteredIndex)}
277 |               onDragEnd={handleDragEnd}
278 |               onDragOver={(e) => handleDragOver(e, filteredIndex)}
279 |               onDragLeave={handleDragLeave}
280 |               onDrop={(e) => handleDrop(e, filteredIndex)}
281 |               title={`${track.title}${track.artist ? ` — ${track.artist}` : ""}`}
282 |             >
283 |               <span className="playlist-item-drag-handle" title="Arrastar para reordenar">
284 |                 ⠿
285 |               </span>
286 |               {onToggleFavorite && (
287 |                 <span
288 |                   className={`playlist-item-favorite ${track.isFavorite ? "favorite-active" : ""}`}
289 |                   onClick={(e) => {
290 |                     e.stopPropagation();
291 |                     onToggleFavorite(track.id);
292 |                   }}
293 |                   title={track.isFavorite ? "Remover dos favoritos" : "Adicionar aos favoritos"}
294 |                 >
295 |                   {track.isFavorite ? "♥" : "♡"}
296 |                 </span>
297 |               )}
298 |               <span className="playlist-item-icon">
299 |                 {track.id === currentTrackId && isPlaying ? "▶" : "🎵"}
300 |               </span>
301 |               <span className="playlist-item-title">{track.title}</span>
302 |               {track.artist && (
303 |                 <span className="playlist-item-artist">{track.artist}</span>
304 |               )}
305 |               <span className="playlist-item-duration">
306 |                 {formatDuration(track.duration)}
307 |               </span>
308 |             </li>
309 |           ))
310 |         )}
311 |       </ul>
312 |       <div className="panel-footer">
313 |         <span>{tracks.length} música{tracks.length !== 1 ? "s" : ""}</span>
314 |         <span>
315 |           {tracks.reduce((acc, t) => acc + t.duration, 0) > 0
316 |             ? formatDuration(tracks.reduce((acc, t) => acc + t.duration, 0))
317 |             : "—:—:—"}
318 |         </span>
319 |       </div>
320 |     </section>
321 |   );
322 | }
